pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and the sent amount; the fuzzer should find amounts != 1 ether
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // keep caller usable
        vm.assume(caller != address(0));
        // restrict sendAmount to a wide but finite range to avoid overflow in vm.deal
        sendAmount = bound(sendAmount, 0, 10 ether);

        // Ensure the caller has the funds to send
        vm.deal(caller, sendAmount);

        // Caller must not have an existing guess: ensure fresh by using a fresh address via prank
        vm.prank(caller);

        bool ok;
        // try calling lockInGuess with arbitrary hash and the fuzzed value
        try c.lockInGuess{value: sendAmount}(bytes32(uint256(0x123))) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference requires exactly 1 ether, so for ANY caller and ANY value != 1 ether,
        // the reference would revert (ok == false). The mutant removes that check and will succeed
        // for some sendAmount != 1 ether (ok == true). We assert the property that calls with amount
        // not equal to 1 ether do NOT succeed on the reference; the buggy mutant will allow some to succeed.
        if (sendAmount != 1 ether) {
            // For the correct contract this must always be false (revert on wrong amount)
            assertTrue(!ok);
        } else {
            // If exact 1 ether is sent, call should succeed and record (we only assert success here)
            assertTrue(ok);
        }
    }
}

