import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and the bytes32 guess; these are the deciding values
    function testFuzz_property(address caller, bytes32 guess) public {
        // keep caller usable (non-zero) and avoid the zero-address which can't receive Ether via prank in some setups
        vm.assume(caller != address(0));

        // fund the caller so it can send 1 ether
        vm.deal(caller, 1 ether);

        // perform the call as the fuzzed caller
        vm.prank(caller);
        bool ok;
        // call lockInGuess with exactly 1 ether
        try c.lockInGuess{value: 1 ether}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property for the reference: if the call succeeded, the stored guess equals the provided guess.
        // We read the public mapping via its auto-generated getter: guesses(address) returns (uint, bytes32) in original
        // However Solidity auto-getter order: for struct mapping, the compiler generates a getter returning the struct members.
        // So we can call c.guesses(caller) to obtain (uint256 blockNum, bytes32 storedGuess).
        (uint256 blockNum, bytes32 storedGuess) = c.guesses(caller);

        // The specification: whenever lockInGuess successfully executes, the stored guess equals the exact input 'guess'.
        // If the call reverted, we cannot assume state changed; so assert only when ok is true OR when there is a recorded block.
        // Use a single assertTrue as required: the condition covers both cases: either the call reverted (ok == false) and
        // no guess was stored (blockNum == 0), or the call succeeded (ok == true) and storedGuess == guess.
        assertTrue((ok == false && blockNum == 0) || (ok == true && storedGuess == guess));
    }
}

