pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address and the provided guess bytes32
    function testFuzz_property(address caller, bytes32 hash) public {
        // admissible constraints: caller cannot be address(0) to make pranking meaningful
        vm.assume(caller != address(0));

        // fund the caller so they can send 1 ether
        vm.deal(caller, 1 ether);

        // compute the expected stored value according to a rule that includes caller and assigned block
        // We cannot read the internal Guess struct directly, but we can reproduce a unique commitment
        // by calling lockInGuess and then checking that a second lock by a different caller would produce
        // a different stored value (i.e., the stored value depends on caller). We do this by letting
        // two distinct callers lock the same hash and then asserting that the contract treated them distinctly

        // pick a second distinct caller address derived from fuzzed caller to keep fuzzing
        address other = address(uint160(uint256(keccak256(abi.encodePacked(caller, hash, block.number)))));
        vm.assume(other != address(0));
        vm.assume(other != caller);
        vm.deal(other, 1 ether);

        // caller locks in their guess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // other locks in the same guess value
        vm.prank(other);
        c.lockInGuess{value: 1 ether}(hash);

        // Now, because the correct contract stores per-address commitments, the two stored guesses
        // must differ when combined with their owner address (i.e., stored value depends on caller).
        // We cannot access internal mapping directly; but we can detect difference via settling: if one
        // of them wins when blockhash matches its stored commitment, the other should not win for the same block.
        // Advance block so both can be settled (their stored block was block.number + 1 at lock time)

        // move to a future block where settlement is allowed
        vm.roll(block.number + 2);

        // Try settling for caller and other and observe whether both receive funds: only at most one should succeed
        uint256 balCallerBefore = caller.balance;
        uint256 balOtherBefore = other.balance;

        vm.prank(caller);
        try c.settle() {
            // settled without revert
        } catch {}

        vm.prank(other);
        try c.settle() {
        } catch {}

        uint256 balCallerAfter = caller.balance;
        uint256 balOtherAfter = other.balance;

        // The general property we assert: both parties cannot both receive 2 ether as payouts for the same hash
        // because the stored commitments are distinct per-caller; the mutant that collapses commitment components
        // could allow both to match the same derived answer causing both to be paid for some inputs.
        // So assert that NOT (both balances increased by 2 ether)
        bool bothPaid = (balCallerAfter - balCallerBefore) >= 2 ether && (balOtherAfter - balOtherBefore) >= 2 ether;
        assertTrue(!bothPaid);
    }
}

