    function setUp() public { c = new C{value: 1 ether}(); }

    // We fuzz over the caller address and an arbitrary bytes32 hash input.
    // The admissible domain: caller != address(0) and caller has 1 ether to pay.
    // General rule: after a successful lockInGuess(hash) on block N, reference stores
    // guesses[caller].guess == keccak256(abi.encodePacked(hash, uint256(N+1))).
    // The mutant that stores keccak256(hash) (omitting the block) will differ
    // whenever keccak256(abi.encodePacked(hash, N+1)) != keccak256(abi.encodePacked(hash)).
    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0));
        // fund caller so they can pay 1 ether
        vm.deal(caller, 1 ether);

        // run as caller and call lockInGuess with 1 ether
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // read the stored guess via the public getter for guesses mapping
        // Solidity auto-generated getter for mapping returns (uint256 block, bytes32 guess)
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(caller);

        // The reference stores guess = keccak256(abi.encodePacked(hash, uint256(storedBlock)))
        // (note storedBlock is already block.number + 1 as set by lockInGuess).
        bytes32 expected = keccak256(abi.encodePacked(hash, storedBlock));

        // Single assertion: the stored guess equals the expected value.
        assertTrue(storedGuess == expected);
    }
}

