        c.lockInGuess{value: 1 ether}(guess);

        // advance one block so settle's require(block.number > storedBlock) can hold
        vm.roll(block.number + 2);

        // Now we want the computed answer in settle to equal the stored guess to trigger payout on correct contract.
        // The answer is keccak256(abi.encodePacked(blockhash(guesses[msg.sender].block))) where guesses[msg.sender].block was block.number+1 at lock.
        // We cannot directly set blockhash for arbitrary historic blocks in tests, but we can exploit that when the block number provided
        // to blockhash refers to the previous block (i.e., current block - 1) then blockhash(current-1) is available.
        // In lockInGuess, stored block = lockBlock + 1. We rolled forward to ensure settle sees block.number > storedBlock.
        // To make answer == guess, we need keccak256(abi.encodePacked(blockhash(storedBlock))) == guess.
        // We cannot control blockhash(storedBlock) directly, but we can choose seed so that guess equals keccak256(abi.encodePacked(blockhash(storedBlock))).
        // The fuzzer will try many seeds; to make the property universal for the correct contract we assert a relation that must hold whenever the answer equals the stored guess: the contract balance decreases by 2 ether after settle. This is a general rule.

        // Record balance before settle
        uint256 before = address(c).balance;

        // actor calls settle
        vm.prank(actor);
        // settle is non-payable
        c.settle();

        uint256 after = address(c).balance;

        // Single assertion: if the stored guess matched the computed answer at settle time, the correct contract pays out 2 ether.
        // We cannot read the internal stored guess directly, but this property can be checked via balances: if before - after == 2 ether then a payout occurred.
        // For the correct contract, whenever the computed answer equals the stored guess it will pay 2 ether; the mutant that zeroes the guess before comparison will prevent that payout for some inputs.
        // So we assert that no impossible payout occurs: if a payout occurred (before - after == 2 ether) then that means the stored guess equaled the answer at compare time; the correct contract allows that — this assertion is simply checking that payouts are exactly 2 ether when they occur.
        // We formulate a universal predicate: after either unchanged or decreased by exactly 2 ether; the correct contract never pays any other amount.
        assertTrue(before == after || before - after == 2 ether);
    }
}

